<script setup lang="ts">
import {ref,onUnmounted} from 'vue'
import {Sparkles,Square} from 'lucide-vue-next'
import type {Document} from '../domain/local-contract'
import {selectedText,type ChatSession,type ChatMessage} from '../tavern/chat-contract'
import {useLocal} from '../stores/local'
import Sheet from '../components/Sheet.vue'
import {freezePlugins,runPluginHook} from './runtime'
import type {PluginReport,PluginReference,PluginSuggestion,PluginTrace} from './contract'
const props=defineProps<{sessionId:string;chat:ChatSession;messages:Document<ChatMessage>[];speakerId:string}>(),emit=defineEmits<{fill:[text:string]}>(),store=useLocal(),opened=ref(false),busy=ref(false),error=ref(''),results=ref<{pluginId:string;suggestion:PluginSuggestion}[]>([]),references=ref<PluginReference[]>([]),trace=ref<PluginTrace[]>([]),names=ref<Record<string,string>>({})
let disposed=false,controller:AbortController|null=null
async function run(){const vault=store.vault;if(!vault||busy.value)return;opened.value=true;busy.value=true;error.value='';results.value=[];controller?.abort();controller=new AbortController();const signal=controller.signal;try{const frozen=await freezePlugins(vault,props.sessionId,props.chat,props.messages,props.speakerId,signal),last=props.messages.filter(row=>!row.value.hidden).at(-1),run=await runPluginHook(vault,frozen.snapshot,'onUserAction',last?selectedText(last.value):'',last?selectedText(last.value):'',props.speakerId,signal);signal.throwIfAborted();const report:PluginReport={assetType:'plugin-report',targetId:props.sessionId,taskId:null,snapshot:frozen.snapshot,trace:run.trace,historical:false,createdAt:new Date().toISOString()};await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'plugin-report:'+crypto.randomUUID(),expectedRevision:0,value:report}],signal,frozen.preconditions);if(disposed||store.vault!==vault)return;references.value=frozen.snapshot.references;trace.value=run.trace;names.value=Object.fromEntries(frozen.snapshot.plugins.map(row=>[row.id,row.value.manifest.name]));results.value=run.outputs.flatMap(row=>(row.output.suggestions||[]).map(suggestion=>({pluginId:row.pluginId,suggestion})))}catch(e){if(!disposed&&!signal.aborted)error.value=(e as Error).message}finally{busy.value=false}}
function sourcePath(id:string){const ref=references.value.find(ref=>ref.id===id);return ref?.kind==='messages'?'/local/chat/'+props.sessionId+'?message='+encodeURIComponent(id):ref?.kind==='memory'?'/local/companions/'+props.chat.companionId:'/local/lorebooks?book='+encodeURIComponent(id)}
function fill(text:string){emit('fill',text);opened.value=false}
onUnmounted(()=>{disposed=true;controller?.abort()})
</script>
<template><button type="button" @click="run"><Sparkles :size="16"/>灵感与资料</button><Sheet v-if="opened" title="灵感与资料" @close="opened=false;controller?.abort()"><div class="plugin-suggestions"><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="busy" @click="controller?.abort()"><Square :size="16"/>停止插件</button><p v-else-if="!results.length" class="final-subtle">还没有建议</p><article v-for="(result,index) in results" :key="index"><small>{{names[result.pluginId]}}</small><strong>{{result.suggestion.title}}</strong><p>{{result.suggestion.text}}</p><div class="final-grid-actions"><RouterLink v-for="id in result.suggestion.sourceIds" :key="id" :to="sourcePath(id)">{{references.find(row=>row.id===id)?.title||'来源'}} ↗</RouterLink><button @click="fill(result.suggestion.text)">填入草稿</button></div></article><details v-if="trace.length"><summary>本次插件记录 · 0 次模型调用</summary><p v-for="(row,index) in trace" :key="index">{{names[row.pluginId]}} · {{row.state==='completed'?'已完成':row.reason}} · {{row.milliseconds}} ms</p></details><RouterLink class="final-text-link" :to="'/local/plugins?session='+sessionId">本会话插件</RouterLink></div></Sheet></template>
<style scoped>.plugin-suggestions{display:grid;gap:20px}.plugin-suggestions>article{display:grid;gap:12px;padding:20px;border:1px solid var(--edge);border-radius:12px}.plugin-suggestions p{white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.plugin-suggestions small{color:var(--quiet)}.plugin-suggestions a{font-size:13px;color:var(--accent)}</style>
